from __future__ import annotations

import os
import re

from .generate import generate
from .schema import fingerprint

_PYPROJECT = '''\
# AUTO-GENERATED by sutra_platform_sdk.package — do not edit by hand.
[build-system]
requires = ["setuptools>=64"]
build-backend = "setuptools.build_meta"

[project]
name = "{dist}"
version = "{version}"
description = "Generated Sutra-OS ontology SDK for {ontology!r} (fingerprint {fingerprint})."
requires-python = ">=3.9"
dependencies = ["sutra-platform-sdk>={runtime}"]

[tool.setuptools]
packages = ["{name}"]
'''

_INIT_TAIL = '''

def client(base_url, **kwargs):
    """A SutraClient with these generated bindings already registered."""
    from sutra_platform_sdk import SutraClient
    return register_all(SutraClient(base_url, **kwargs))
'''


def dist_name(name: str) -> str:
    return re.sub(r"[_.]+", "-", name).lower()


def write_package(schema: dict, out_dir: str, *, name: str,
                  ontology: str = "sutra", version: str = "0.1.0",
                  runtime: str = "0.2.0") -> dict:
    if not name.isidentifier():
        raise ValueError(f"{name!r} is not a valid Python package name")
    fp = fingerprint(schema)
    pinned = f"{version}+{fp}"
    package_dir = os.path.join(out_dir, name)
    os.makedirs(package_dir, exist_ok=True)
    with open(os.path.join(package_dir, "__init__.py"), "w", encoding="utf-8") as handle:
        handle.write(generate(schema, None, ontology=ontology))
        handle.write(_INIT_TAIL)
    with open(os.path.join(out_dir, "pyproject.toml"), "w", encoding="utf-8") as handle:
        handle.write(_PYPROJECT.format(dist=dist_name(name), name=name,
                                       version=pinned, ontology=ontology,
                                       fingerprint=fp, runtime=runtime))
    return {"dir": out_dir, "package": name, "dist": dist_name(name),
            "version": pinned, "fingerprint": fp}
